import { vi } from 'vitest';

// ---------------------------------------------------------------------------
// Test stand-in for vite-plugin-pwa's virtual:pwa-register/react
// ---------------------------------------------------------------------------
// The real module is generated by the VitePWA plugin at build time; vitest
// doesn't load that plugin, so vitest.config.js aliases the virtual specifier
// here. Tests mutate `swState.needRefresh` to show/hide the prompt and assert
// on `updateServiceWorker`.

export const swState = { needRefresh: false };
export const updateServiceWorker = vi.fn();

export function useRegisterSW() {
  return {
    needRefresh: [swState.needRefresh, (v) => { swState.needRefresh = v; }],
    updateServiceWorker,
  };
}
